class Vehicle {
    String describe() {
        return "vehicle";
    }
}

class Bicycle extends Vehicle {
    @Override
    String describe() {
        return "bicycle";
    }
}

public class Garage {

    public static String describeAll(Vehicle[] vehicles) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < vehicles.length; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(vehicles[i].describe());
        }
        return sb.toString();
    }

    public static int countBicycles(Vehicle[] vehicles) {
        int count = 0;
        for (Vehicle v : vehicles) {
            if (v instanceof Bicycle) {
                count++;
            }
        }
        return count;
    }
}
